using Commerce;

namespace Commerce.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem ---

    [TestMethod]
    public void AddItem_SingleItem_AppearsInItems()
    {
        _cart.AddItem("SKU-1", 9.99m, 2);

        Assert.AreEqual(1, _cart.Items.Count);
        Assert.AreEqual("SKU-1", _cart.Items[0].Sku);
        Assert.AreEqual(9.99m, _cart.Items[0].Price);
        Assert.AreEqual(2, _cart.Items[0].Qty);
    }

    [TestMethod]
    public void AddItem_MultipleItems_AllAppear()
    {
        _cart.AddItem("A", 5m, 1);
        _cart.AddItem("B", 10m, 3);

        Assert.AreEqual(2, _cart.Items.Count);
    }

    // --- RemoveItem ---

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("X", 1m, 1);

        Assert.IsTrue(_cart.RemoveItem("X"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("X", 1m, 1);
        _cart.RemoveItem("X");

        Assert.AreEqual(0, _cart.Items.Count);
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    public void RemoveItem_RemovesDuplicateSkus()
    {
        _cart.AddItem("DUP", 2m, 1);
        _cart.AddItem("DUP", 3m, 2);

        Assert.IsTrue(_cart.RemoveItem("DUP"));
        Assert.AreEqual(0, _cart.Items.Count);
    }

    // --- GetTotal ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_SingleItem_ReturnsPriceTimesQty()
    {
        _cart.AddItem("W", 7.50m, 4);

        Assert.AreEqual(30.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _cart.AddItem("A", 10m, 2); // 20
        _cart.AddItem("B", 5m, 3);  // 15

        Assert.AreEqual(35m, _cart.GetTotal());
    }

    // --- ApplyPromoCode ---

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReturnsTrue()
    {
        Assert.IsTrue(_cart.ApplyPromoCode("SAVE10"));
    }

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReducesTotal()
    {
        _cart.AddItem("P", 100m, 1);
        _cart.ApplyPromoCode("SAVE10");

        Assert.AreEqual(90m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_HalfOff_ReducesTotalBy50Percent()
    {
        _cart.AddItem("P", 80m, 1);
        _cart.ApplyPromoCode("HALF");

        Assert.AreEqual(40m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_CaseInsensitive()
    {
        _cart.AddItem("P", 100m, 1);
        _cart.ApplyPromoCode("save10");

        Assert.AreEqual(90m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        Assert.IsFalse(_cart.ApplyPromoCode("BOGUS"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_DoesNotAffectTotal()
    {
        _cart.AddItem("P", 50m, 1);
        _cart.ApplyPromoCode("BOGUS");

        Assert.AreEqual(50m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterRemovingItem_UpdatesCorrectly()
    {
        _cart.AddItem("A", 10m, 1);
        _cart.AddItem("B", 20m, 1);
        _cart.RemoveItem("A");

        Assert.AreEqual(20m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_PromoAppliedToMultipleItems()
    {
        _cart.AddItem("A", 50m, 2); // 100
        _cart.AddItem("B", 25m, 4); // 100
        _cart.ApplyPromoCode("SAVE10");

        Assert.AreEqual(180m, _cart.GetTotal()); // 200 - 10%
    }
}

